import {buildFeedback,evidenceNote} from './feedback.js';
import {QUESTIONS,BANK_VERSION} from './bank.js';
import {createAttempt,getNextQuestion,submitAnswer,getProgress,getReport,validateAttempt} from './engine.js';

const $=s=>document.querySelector(s);
const STORE='nurkanat-diagnostic-preview-v1';
const LANG='nurkanat-language';
const LEVELS=['A1','A2','B1','B2','C1'];
const WA='https://wa.me/77085501378';
const app=$('#app');
let language='ru',attempt=null,screen='home',selected=undefined,modalFocus=null;
let heard=new Set(),saveOk=true,storageConflict=false,toastTimer;
try{language=localStorage.getItem(LANG)==='en'?'en':'ru';const saved=JSON.parse(localStorage.getItem(STORE)||'null');if(saved?.bank===BANK_VERSION&&validateAttempt(saved.attempt,QUESTIONS)){attempt=saved.attempt;heard=new Set(Array.isArray(saved.heard)?saved.heard:[]);}}catch{saveOk=false;}
const t=(ru,en)=>language==='ru'?ru:en;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span aria-hidden="true">↗</span>';
const tick='<span class="check-mark" aria-hidden="true">✓</span>';
const domainName=d=>({language:t('Грамматика и лексика','Grammar & vocabulary'),reading:t('Чтение','Reading'),listening:t('Аудирование','Listening')})[d];
const domainShort=d=>({language:t('Язык','Language use'),reading:t('Чтение','Reading'),listening:t('Аудирование','Listening')})[d];
const waLink=message=>WA+'?text='+encodeURIComponent(message);
const courseMessage=format=>t(`Здравствуйте, Нұрқанат! Хочу узнать о ${format==='intensive'?'интенсивном':'стандартном'} курсе английского.`, `Hello, Nurkanat! I'd like to learn about your ${format==='intensive'?'intensive':'standard'} English course.`);
function languageButton(){return `<button class="language-switch" data-action="language" aria-label="${t('Switch to English','Переключить на русский')}"><span ${language==='ru'?'class="active"':''}>RU</span><span class="language-divider">/</span><span ${language==='en'?'class="active"':''}>EN</span></button>`;}
function brand(){return `<a href="#home" class="brand" data-action="home"><span class="brand-mark" aria-hidden="true">n<span>·</span></span><span class="brand-copy">${t('Нұрқанат Дайраш','Nurkanat Dairash')}<small>${t('АНГЛИЙСКИЙ С ПОНИМАНИЕМ','ENGLISH WITH UNDERSTANDING')}</small></span></a>`;}
function previewBanner(){return `<div class="preview-banner">${t('Предварительная версия · прохождение бесплатно · результаты требуют проверки преподавателем','Preview edition · free to try · results need teacher confirmation')}</div>`;}
function save(){if(storageConflict)return;try{localStorage.setItem(STORE,JSON.stringify({bank:BANK_VERSION,attempt,heard:[...heard]}));saveOk=true;}catch{saveOk=false;}}
function toast(message){const box=$('#toast');box.textContent=message;box.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.hidden=true,4200);}
function render(){document.documentElement.lang=language;document.title=t('Ваш английский, понятнее — Нұрқанат Дайраш','Understand your English — Nurkanat Dairash');if(screen==='quiz')renderQuiz();else if(screen==='result')renderResult();else renderHome();}
function focusMain(){requestAnimationFrame(()=>{const heading=$('#main h1')||$('#main h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}});}
function go(next){closeModal();screen=next;selected=undefined;render();window.scrollTo({top:0,behavior:'instant'});focusMain();}
function sampleReport(){return `<div class="hero-visual"><div class="orbit-label"><span></span> ${t('Больше, чем одна буква','More than a single label')}</div><div class="sample-report"><div class="report-top"><span class="report-label">${t('ВАШ АНГЛИЙСКИЙ','YOUR ENGLISH')}</span><span class="report-badge">${t('Пример отчёта','Sample report')}</span></div><div class="report-score-row"><div class="report-level">A2<span>→ B1</span></div><span class="report-status">${t('Следующий шаг<br>уже понятен','Your next step<br>comes into focus')}</span></div><div class="report-scale">${LEVELS.map((l,i)=>`<div class="scale-step ${i===1?'active':''}"><span>${l}</span></div>`).join('')}</div><div class="sample-skills">${[[t('Чтение','Reading'),'B1',74],[t('Аудирование','Listening'),'A2',47],[t('Грамматика и лексика','Grammar & vocabulary'),'A2',53]].map(([name,l,v])=>`<div class="sample-skill"><div><span>${name}</span><strong>${l}</strong></div><div class="skill-track"><span class="skill-fill" style="width:${v}%"></span></div></div>`).join('')}</div><div class="report-note"><span class="note-icon" aria-hidden="true">✦</span><p>${t('Вы уже многое понимаете.<br><strong>Следующий фокус — английский на слух.</strong>','You already understand a lot.<br><strong>Next focus: understanding spoken English.</strong>')}</p></div><div class="sample-report-foot">${t('Речь и письмо — отдельно с преподавателем','Speaking & writing — assessed with your teacher')}</div></div><div class="floating-note">${tick}<div>${t('Ваш уровень. Ваш маршрут.','Your level. Your way forward.')}<small>${t('Понятно, с чего начать','Know where to begin')}</small></div></div></div>`;}
function renderHome(){
  const progress=attempt?getProgress(attempt):null;
  app.innerHTML=`${previewBanner()}<header class="site-header container">${brand()}<nav class="nav-links" aria-label="${t('Главное меню','Main navigation')}"><a href="#how">${t('Как это работает','How it works')}</a><a href="#formats">${t('Диагностика','Assessment')}</a><a href="#courses">${t('Курсы','Courses')}</a></nav><div class="header-tools">${languageButton()}<a class="header-contact" href="${waLink(t('Здравствуйте! У меня вопрос о диагностике английского.','Hello! I have a question about the English assessment.'))}" target="_blank" rel="noopener">WhatsApp ${arrow}</a></div></header>
  <main id="main">
    <section class="hero container" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-dot"></span>${t('ВАШ СЛЕДУЮЩИЙ ШАГ В АНГЛИЙСКОМ','YOUR NEXT STEP IN ENGLISH')}</div><h1 id="hero-title">${t('Ваш английский.<br><span>Теперь понятнее.</span>','Your English.<br><span>Now, clearer.</span>')}</h1><p class="hero-description">${t('Узнайте, что вы уже умеете, где есть пробелы и с чего начать дальше. Диагностика навыков — и подходящий маршрут обучения.','Discover what you can already do, where the gaps are, and what to work on next. A picture of your skills — and a clear learning direction.')}</p><div class="hero-actions"><button class="button primary" data-action="prepare" data-mode="full">${t('Узнать свой уровень','Find my English level')} ${arrow}</button><a class="text-link" href="#formats">${t('Выбрать формат','Explore the options')} <span aria-hidden="true">↓</span></a></div><div class="hero-notes"><span>${tick} A1–C1</span><span>${tick} ${t('На телефоне и компьютере','Phone & desktop')}</span><span>${tick} ${t('С понятным разбором','Clear, useful feedback')}</span></div>${progress?`<div class="resume-banner"><div><strong>${progress.complete?t('Ваш результат сохранён','Your result is saved'):t('Продолжим с того же места?','Pick up where you left off?')}</strong><span>${t(`Выполнено заданий: ${progress.answered} из ${progress.total}`,`${progress.answered} of ${progress.total} questions completed`)}</span></div><button class="text-link" data-action="resume">${progress.complete?t('Открыть','View result'):t('Продолжить','Continue')} →</button></div>`:''}</div>${sampleReport()}</section>
    <div class="principle-strip"><div class="container"><span>${t('Чтение','Reading')}</span><span class="strip-star">✦</span><span>${t('Аудирование','Listening')}</span><span class="strip-star">✦</span><span>${t('Грамматика и лексика','Grammar & vocabulary')}</span><span class="strip-star">✦</span><span>${t('Личный следующий шаг','Your personal next step')}</span></div></div>
    <section class="section container" id="how"><div class="section-head"><div><p class="section-kicker">01 / ${t('ОТ ВОПРОСОВ К ЯСНОСТИ','FROM QUESTIONS TO CLARITY')}</p><h2 class="section-title">${t('«Знаю английский» —<br>у каждого по-своему.','“I know some English”<br>means something different to everyone.')}</h2></div><p class="section-lead">${t('Можно легко читать и теряться в разговоре. Поэтому мы смотрим на отдельные навыки, а не только на общий балл.','You might read comfortably and still struggle to follow a conversation. That’s why we look at individual skills, not just a total score.')}</p></div><div class="method-grid">${[[t('Пройдите задания','Work through the tasks'),t('Сложность меняется по вашим ответам. Выберите вариант или честно отметьте «Не знаю».','Question difficulty adjusts to your answers. Choose an answer or simply select “I don’t know”.')],[t('Поймите свой профиль','Understand your profile'),t('Получите предварительный ориентир по навыкам и несколько конкретных направлений для практики.','Get a provisional picture of your skills and a few practical areas to work on.')],[t('Выберите следующий шаг','Choose your next step'),t('Уточните речь и письмо с преподавателем или обсудите группу, подходящую вашему уровню.','Assess speaking and writing with your teacher, or discuss a course that fits your level.')]].map(([title,desc],i)=>`<article class="method-card"><span class="step-number">0${i+1}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div></section>
    <section class="section offer-section" id="formats"><div class="container"><div class="section-head"><div><p class="section-kicker">02 / ${t('ВЫБЕРИТЕ ГЛУБИНУ','CHOOSE HOW DEEP TO GO')}</p><h2 class="section-title">${t('От первого ориентира<br>до личного разбора.','From a first impression<br>to a personal assessment.')}</h2></div><p class="section-lead">${t('Сейчас все онлайн-задания можно попробовать бесплатно. Ниже — планируемые форматы; оплата пока не принимается.','You can try all online tasks free in this preview. These are the planned options; payments are not enabled.')}</p></div><div class="offer-grid">
      <article class="offer-card"><span class="pill">${t('ПЕРВОЕ ЗНАКОМСТВО','A FIRST LOOK')}</span><h3>${t('Быстрый ориентир','Quick orientation')}</h3><p class="offer-meta">${t('12 заданий · грамматика, лексика и чтение','12 questions · language use and reading')}</p><div class="offer-price">0 ₸</div><p>${t('Для первого представления о своём английском. Без аудирования и оценки речи.','A starting point for understanding your English. Listening and speaking are not assessed.')}</p><ul class="feature-list"><li>${tick}${t('Короткий формат','A short introduction')}</li><li>${tick}${t('Предварительный результат','A provisional result')}</li><li>${tick}${t('Рекомендации для следующего шага','Suggestions for your next step')}</li></ul><div class="offer-footer"><button class="button secondary wide" data-action="prepare" data-mode="quick">${t('Начать короткий тест','Try the quick check')} ${arrow}</button></div></article>
      <article class="offer-card featured"><div class="offer-ribbon">${t('БОЛЬШЕ О ВАШЕМ АНГЛИЙСКОМ','A FULLER PICTURE')}</div><span class="pill">${t('ОНЛАЙН-ДИАГНОСТИКА','ONLINE ASSESSMENT')}</span><h3>${t('Профиль навыков','Your skill profile')}</h3><p class="offer-meta">${t('30 заданий в текущей версии · 3 раздела','30 questions in this edition · 3 sections')}</p><div class="offer-price">1 000 ₸<small>${t('планируемая цена','planned price')}</small></div><p>${t('Более подробный взгляд на чтение, понимание на слух и знание языка.','A closer look at reading, listening, and your understanding of English grammar and vocabulary.')}</p><ul class="feature-list"><li>${tick}${t('Задания с изменяемой сложностью','Tasks that adjust in difficulty')}</li><li>${tick}${t('Аудиозадания','Listening tasks')}</li><li>${tick}${t('Профиль навыков и разбор ответов','Skill profile and answer explanations')}</li><li>${tick}${t('План первой недели практики','Your first week of practice')}</li></ul><div class="offer-footer"><button class="button primary wide" data-action="prepare" data-mode="full">${t('Попробовать бесплатно','Try it free')} ${arrow}</button></div></article>
      <article class="offer-card"><span class="pill">${t('С ПРЕПОДАВАТЕЛЕМ','WITH YOUR TEACHER')}</span><h3>${t('Полная диагностика','Complete assessment')}</h3><p class="offer-meta">${t('Онлайн-часть + речь и письмо','Online tasks + speaking and writing')}</p><div class="offer-price">5 000 ₸<small>${t('планируемая полная цена','planned total price')}</small></div><p>${t('Обсудите ваши цели лично и дополните онлайн-профиль оценкой речи и письма.','Discuss your goals in person and complete your online profile with speaking and writing assessment.')}</p><ul class="feature-list"><li>${tick}${t('Всё из онлайн-диагностики','Everything in the online assessment')}</li><li>${tick}${t('Разговор с преподавателем','A conversation with your teacher')}</li><li>${tick}${t('Проверка письменной работы','Teacher-reviewed writing')}</li><li>${tick}${t('Личная рекомендация и план практики','A personal recommendation and practice plan')}</li></ul><div class="offer-footer"><a class="button secondary wide" href="${waLink(t('Здравствуйте, Нұрқанат! Хочу узнать о полной диагностике английского с оценкой речи и письма.','Hello, Nurkanat! I’m interested in the complete assessment, including speaking and writing.'))}" target="_blank" rel="noopener">${t('Обсудить диагностику','Ask about the assessment')} ${arrow}</a></div></article>
    </div><p class="fine-print">${t('Это авторская диагностика для выбора обучения, а не официальный экзамен или сертификат CEFR. Вопросы и шкала этой версии ещё проходят проверку.','This is an independent placement assessment, not an official examination or CEFR certificate. This edition’s questions and scoring are still being evaluated.')}</p></div></section>
    <section class="section container"><div class="teacher-strip"><img class="teacher-photo" src="assets/teacher.jpg" alt="${t('Нұрқанат Дайраш за рабочим столом','Nurkanat Dairash at his desk')}" loading="lazy" width="720" height="1280"><div class="teacher-copy"><p class="section-kicker">${t('ВАШ ПРЕПОДАВАТЕЛЬ','MEET YOUR TEACHER')}</p><h2>${t('За результатом —<br>живой разговор.','Behind every result,<br>a real conversation.')}</h2><p>${t('Я Нұрқанат. Помогу разобраться в результате, уточнить ваши цели и выбрать группу, в которой будет комфортно учиться и двигаться дальше.','I’m Nurkanat. I’ll help you understand your result, talk through your goals, and find a group where you can learn comfortably and keep progressing.')}</p><a class="text-link" href="https://nurkanat-tau.github.io/#about" target="_blank" rel="noopener">${t('Больше обо мне','More about me')} ${arrow}</a></div><span class="teacher-decoration" aria-hidden="true">n.</span></div></section>
    ${coursesSection()}
    <section class="section container faq-section"><div><p class="section-kicker">04 / ${t('ПЕРЕД НАЧАЛОМ','BEFORE YOU BEGIN')}</p><h2 class="section-title">${t('Всё понятно.<br>Даже до теста.','A little clarity.<br>Before you even begin.')}</h2><a class="text-link" href="${WA}" target="_blank" rel="noopener">${t('Остался вопрос? Напишите мне','Still have a question? Message me')} ${arrow}</a></div><div class="faq-list">${faq().map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></section>
    <section class="closing-section container"><div><p class="section-kicker">${t('НАЧНИТЕ С ПОНИМАНИЯ','START WITH UNDERSTANDING')}</p><h2>${t('Ваш английский уже есть.<br>Узнайте, какой следующий шаг.','You already have a starting point.<br>Discover what comes next.')}</h2></div><button class="button primary" data-action="prepare" data-mode="full">${t('Пройти диагностику','Try the assessment')} ${arrow}</button></section>
  </main><footer class="site-footer"><div class="footer-inner container">${brand()}<p>© ${new Date().getFullYear()} ${t('Нұрқанат Дайраш','Nurkanat Dairash')}<br>${t('Английский с пониманием.','English with understanding.')}</p><div><button class="text-link" data-action="privacy">${t('О ваших данных','Your data')}</button><a href="${WA}" target="_blank" rel="noopener">WhatsApp ${arrow}</a></div></div></footer>`;
}
function coursesSection(){return `<section class="course-section" id="courses"><div class="container"><div class="section-head"><div><p class="section-kicker">03 / ${t('ОТ УРОВНЯ К ПРОГРЕССУ','FROM PLACEMENT TO PROGRESS')}</p><h2 class="section-title">${t('Знать свой уровень — начало.<br>Дальше — ваш темп.','Knowing your level is a start.<br>Next, find your pace.')}</h2></div><p class="section-lead">${t('Выберите формат, который вписывается в вашу жизнь. Группу и нагрузку обсудим с учётом ваших целей.','Choose a format that fits your life. We’ll discuss the group and workload around your goals.')}</p></div><div class="course-grid">${['standard','intensive'].map((f,i)=>`<article class="course-card"><div><span class="pill">${i?t('БОЛЬШЕ ПРАКТИКИ В НЕДЕЛЮ','MORE PRACTICE EACH WEEK'):t('ПОСЛЕДОВАТЕЛЬНЫЙ ТЕМП','A STEADY PACE')}</span><h3>${i?t('Интенсив','Intensive'):t('Стандартный курс','Standard course')}</h3><p>${i?t('Для тех, кто готов выделить больше времени на занятия и самостоятельную практику.','For learners ready to make more time for lessons and independent practice.'):t('Чтобы встроить регулярный английский в работу, учёбу и повседневную жизнь.','Build regular English study around your work, studies, and everyday life.')}</p></div><div class="course-number">${i?'3':'6'}<span>${t(i?'месяца*':'месяцев*','months*')}</span></div><a class="button ${i?'primary':'secondary'}" href="${waLink(courseMessage(f))}" target="_blank" rel="noopener">${t('Обсудить курс в WhatsApp','Discuss this course on WhatsApp')} ${arrow}</a></article>`).join('')}</div><p class="fine-print">${t('* Примерная длительность программы на уровень. Расписание, стоимость и доступные группы уточняются лично. Результат зависит от стартового уровня и практики.','* Approximate programme duration per level. Schedule, fees, and available groups are discussed individually. Progress depends on your starting point and practice.')}</p></div></section>`;}
function faq(){return [
  [t('Насколько точным будет результат?','How accurate is the result?'),t('Эта предварительная версия даёт ориентир по выполненным онлайн-заданиям. Вопросы и правила оценки ещё проверяются. Речь и письмо нужно оценить с преподавателем; точное разделение на начало, середину и конец уровня пока не заявляется.','This preview gives an estimate based on the online tasks you complete. The questions and scoring rules are still being evaluated. Speaking and writing need teacher assessment; precise beginning, middle, and upper-level subdivisions are not claimed yet.')],
  [t('Нужно ли сейчас платить?','Do I need to pay now?'),t('Нет. В этой версии прохождение бесплатно. Цены 1 000 ₸ и 5 000 ₸ показывают планируемые форматы. Сайт не принимает оплату и не запрашивает данные карты.','No. This edition is free to try. The 1,000 ₸ and 5,000 ₸ prices describe planned options. This site does not accept payments or request card details.')],
  [t('Можно пройти с телефона?','Can I use my phone?'),t('Да. Для полной онлайн-части нужен звук, желательно наушники. Перед началом можно проверить аудио. Если встроенный браузер мешает воспроизведению, откройте ссылку в обычном браузере.','Yes. The full online route needs audio, preferably with headphones. You can test the sound before starting. If an in-app browser prevents playback, open the link in your regular browser.')],
  [t('Что будет, если закрыть страницу?','What if I close the page?'),t('Ответы сохраняются в этом браузере на этом устройстве, если доступно локальное хранилище. Возвращайтесь через тот же браузер. Очистка данных браузера или приватный режим могут удалить прогресс.','Answers are saved in this browser on this device when local storage is available. Return using the same browser. Clearing browser data or using private browsing may remove progress.')],
  [t('Как проходят речь и письмо?','How are speaking and writing assessed?'),t('Вы договариваетесь с Нұрқанатом о разговоре и письменной работе в WhatsApp. В этой версии сайт не бронирует время и не принимает письменные работы.','Arrange a conversation and a writing task with Nurkanat through WhatsApp. This edition does not book appointments or collect writing submissions.')],
  [t('После теста обязательно записываться на курс?','Do I have to join a course afterwards?'),t('Нет. Результат и рекомендации остаются у вас. Если захотите продолжить обучение, можно обсудить подходящую группу.','No. Your result and recommendations are yours to keep. If you’d like to continue learning, you can discuss a suitable group.')]
];}
function openModal(content){modalFocus=document.activeElement;const overlay=$('#overlay');overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="modal-close" data-action="close" aria-label="${t('Закрыть','Close')}">×</button>${content}</section>`;overlay.hidden=false;document.body.classList.add('modal-open');requestAnimationFrame(()=>overlay.querySelector('.modal').focus());}
function closeModal(){const overlay=$('#overlay');if(!overlay.hidden){overlay.hidden=true;overlay.innerHTML='';document.body.classList.remove('modal-open');modalFocus?.focus?.();}}
function prepare(mode){
  if(attempt&&!getProgress(attempt).complete){openModal(`<p class="section-kicker">${t('ПРОГРЕСС СОХРАНЁН','PROGRESS SAVED')}</p><h2 id="modal-title">${t('Продолжить или начать заново?','Continue or start again?')}</h2><p>${t('Новая попытка заменит сохранённые ответы в этом браузере.','A new attempt will replace the answers saved in this browser.')}</p><div class="modal-actions"><button class="button primary" data-action="resume">${t('Продолжить','Continue')}</button><button class="button secondary" data-action="preflight" data-mode="${mode}">${t('Начать заново','Start again')}</button></div>`);return;}preflight(mode);
}
function preflight(mode){const full=mode==='full';const sample=QUESTIONS.find(q=>q.domain==='listening');openModal(`<p class="section-kicker">${t('ПЕРЕД НАЧАЛОМ','BEFORE YOU START')}</p><h2 id="modal-title">${full?t('Посмотрим на ваш английский.','Let’s explore your English.'):t('Начнём с короткого ориентира.','Let’s start with a quick check.')}</h2><p>${full?t('30 заданий: язык, чтение и аудирование. Сложность подбирается отдельно для каждого раздела.','30 tasks covering language use, reading, and listening. Difficulty adjusts separately for each section.'):t('12 заданий по языку и чтению. Этот короткий формат даёт только предварительный ориентир.','12 language-use and reading tasks. This short route gives only an initial estimate.')}</p><ul class="preflight-list"><li>${tick}${t('Отвечайте самостоятельно, без переводчика.','Work independently, without a translator.')}</li><li>${tick}${t('Можно выбрать «Не знаю» — это нормально.','You can choose “I don’t know” — that’s fine.')}</li><li>${tick}${t('Прогресс сохраняется в этом браузере.','Your progress is saved in this browser.')}</li></ul>${full?`<div class="audio-panel"><strong>${t('Проверьте звук','Check your audio')}</strong><p>${t('В этой версии используется синтезированный голос. Послушайте пример перед началом.','This preview uses a synthetic voice. Play this sample before you begin.')}</p><audio controls preload="none" src="${esc(sample?.audio)}" aria-label="${t('Проверка звука','Audio check')}"></audio><label class="check-label"><input type="checkbox" id="audio-confirm">${t('Звук слышен, я готов(а)','I can hear the audio and I’m ready')}</label></div>`:''}<div class="notice">${t('Пробная версия. Оплаты нет. Результат предварительный, речь и письмо здесь не оцениваются.','Free preview. No payment. Results are provisional; speaking and writing are not assessed here.')}</div><div class="modal-actions"><button class="button primary wide" data-action="start" data-mode="${mode}" ${full?'disabled':''}>${t('Начать диагностику','Start assessment')} ${arrow}</button></div>`);const confirm=$('#audio-confirm');if(confirm)confirm.addEventListener('change',()=>$('#overlay [data-action="start"]').disabled=!confirm.checked);}
function start(mode){if(storageConflict){location.reload();return;}attempt=createAttempt(mode,`${Date.now()}-${Math.random().toString(36).slice(2)}`);heard=new Set();save();go('quiz');}
function appTop(){return `<div class="app-top container">${brand()}<div class="header-tools">${languageButton()}<button class="text-link" data-action="pause">${t('Сохранить и выйти','Save & leave')} <span aria-hidden="true">↗</span></button></div></div>`;}
function renderQuiz(){if(!attempt){go('home');return;}const progress=getProgress(attempt);if(progress.complete){screen='result';renderResult();return;}const q=getNextQuestion(attempt,QUESTIONS);if(!q){app.innerHTML=`<main id="main" class="container empty-state"><h1>${t('Не удалось продолжить','Unable to continue')}</h1><p>${t('Ответы сохранены. Вернитесь к началу или попробуйте снова.','Your answers are saved. Return home or try again.')}</p><button class="button primary" data-action="home">${t('На главную','Back home')}</button></main>`;return;}
  app.innerHTML=`${previewBanner()}<div class="app-shell">${appTop()}<main id="main" class="container"><div class="app-progress"><div><span>${t('ВАША ДИАГНОСТИКА','YOUR ASSESSMENT')}</span><strong>${progress.answered} / ${progress.total}</strong></div><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="${progress.total}" aria-valuenow="${progress.answered}" aria-label="${t('Выполнено заданий','Questions completed')}"><div class="progress-fill" style="width:${progress.percent}%"></div></div></div><div class="app-layout"><section class="question-card"><div class="question-header"><span class="question-number">${t('ЗАДАНИЕ','QUESTION')} ${String(progress.answered+1).padStart(2,'0')}</span><span class="question-skill">${domainName(q.domain)}</span></div>${q.passage?`<div class="passage" lang="en">${esc(q.passage)}</div>`:''}${q.domain==='listening'?`<div class="audio-panel"><div class="audio-heading"><span aria-hidden="true">◉</span><strong>${t('Сначала послушайте запись','Listen to the recording first')}</strong></div><audio id="question-audio" controls preload="metadata" src="${esc(q.audio)}" aria-label="${t('Запись к заданию','Question recording')}"></audio><p>${t('В пробной версии запись можно слушать повторно.','In this preview you can replay the recording.')}</p><p class="audio-error" id="audio-error" hidden>${t('Запись не загрузилась. Проверьте соединение и попробуйте снова. Ошибка звука не должна влиять на ваш уровень.','The recording could not load. Check your connection and retry. An audio error should not affect your result.')} <button class="text-link" data-action="retry-audio">${t('Повторить','Retry')}</button></p></div>`:''}<h1 class="question-title" lang="en">${esc(q.prompt)}</h1><div class="answer-list" role="group" aria-label="${t('Варианты ответа','Answer options')}">${q.options.map((o,i)=>`<button class="answer-option ${selected===i?'selected':''}" data-action="answer" data-index="${i}" aria-pressed="${selected===i}" lang="en"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span><span class="answer-check" aria-hidden="true">${selected===i?'✓':''}</span></button>`).join('')}<button class="answer-option idk ${selected===null?'selected':''}" data-action="unknown" aria-pressed="${selected===null}"><span class="option-letter">—</span><span>${t('Не знаю','I don’t know')}</span></button></div><div class="question-actions"><span class="save-status" role="status">${saveOk?t('✓ Прогресс сохранён на устройстве','✓ Progress saved on this device'):t('Не удалось сохранить на устройстве','Could not save on this device')}</span><button class="button primary" id="next-answer" data-action="submit" ${storageConflict||selected===undefined||q.domain==='listening'&&!heard.has(q.id)?'disabled':''}>${progress.remaining===1?t('Посмотреть результат','View my result'):t('Далее','Continue')} <span aria-hidden="true">→</span></button></div>${q.domain==='listening'&&!heard.has(q.id)?`<p class="audio-required" id="audio-required">${t('Включите запись, чтобы ответить на задание.','Play the recording before submitting your answer.')}</p>`:''}</section><aside class="quiz-sidebar"><p class="section-kicker">${t('ШАГ ЗА ШАГОМ','ONE STEP AT A TIME')}</p><h2>${t('Просто отвечайте<br>в своём темпе.','Take it one<br>question at a time.')}</h2><p>${t('Сложные вопросы — часть диагностики. Не нужно знать каждый ответ.','Difficult questions are part of the assessment. You don’t need to know every answer.')}</p><div class="section-steps">${(attempt.mode==='quick'?['language','reading']:['language','reading','listening']).map((d,i)=>{const count=attempt.answers.filter(a=>a.domain===d).length;const total=d==='language'?(attempt.mode==='quick'?6:12):(attempt.mode==='quick'?6:9);return `<div class="section-step ${q.domain===d?'current':count>=total?'done':''}"><span>${count>=total?'✓':i+1}</span><div>${domainName(d)}<small>${count} / ${total}</small></div></div>`;}).join('')}</div><div class="sidebar-note">${t('Речь и письмо оцениваются отдельно с преподавателем.','Speaking and writing are assessed separately with your teacher.')}</div></aside></div></main></div>`;
  const audio=$('#question-audio');if(audio){audio.addEventListener('timeupdate',()=>{if(!audio.error&&!audio.paused&&audio.readyState>=2&&audio.currentTime>=0.5&&!heard.has(q.id)){heard.add(q.id);save();$('#audio-required')?.remove();updateNext();}});audio.addEventListener('error',()=>{heard.delete(q.id);save();$('#audio-error').hidden=false;updateNext();});}
}
function updateNext(){if(!attempt)return;const q=getNextQuestion(attempt,QUESTIONS);const btn=$('#next-answer');if(btn)btn.disabled=storageConflict||selected===undefined||q.domain==='listening'&&!heard.has(q.id);}
function choose(value){selected=value;document.querySelectorAll('.answer-option').forEach(btn=>{const is=btn.dataset.action==='unknown'?value===null:Number(btn.dataset.index)===value;btn.classList.toggle('selected',is);btn.setAttribute('aria-pressed',String(is));const check=btn.querySelector('.answer-check');if(check)check.textContent=is?'✓':'';});updateNext();}
function submit(){if(storageConflict){location.reload();return;}if(selected===undefined)return;const q=getNextQuestion(attempt,QUESTIONS);if(q.domain==='listening'&&!heard.has(q.id))return;try{attempt=submitAnswer(attempt,q,selected);save();selected=undefined;const complete=getProgress(attempt).complete;if(complete)go('result');else{renderQuiz();window.scrollTo({top:0,behavior:'instant'});focusMain();}}catch{toast(t('Не удалось сохранить ответ. Попробуйте ещё раз.','Could not save your answer. Please try again.'));}}
function resultDomains(report){return Array.isArray(report.domains)?report.domains:Object.entries(report.domains).map(([domain,v])=>({domain,...v}));}
function levelLabel(info){if(!info?.assessed&&info?.assessed!==undefined)return t('Не оценивалось','Not assessed');if(info?.belowFloor)return t('Нужна проверка основ','Foundations check needed');if(Number.isInteger(info?.level))return LEVELS[info.level];if(info?.range&&Number.isInteger(info.range.upper)){const lower=info.range.lower===null?t('Ниже A1','Below A1'):LEVELS[info.range.lower];return lower===LEVELS[info.range.upper]?lower:`${lower}–${LEVELS[info.range.upper]}`;}return t('Требует уточнения','Needs confirmation');}
function getSkillCopy(domain,level){const high=Number(level)>=3;return {
  language:high?t('Продолжайте развивать точность формулировок, сочетания слов и оттенки значения.','Keep developing precise wording, natural word combinations, and shades of meaning.'):t('Практикуйте частые конструкции и сочетания слов в коротких собственных примерах.','Practise common sentence patterns and word combinations in short examples of your own.'),
  reading:high?t('Читайте тексты с разными точками зрения и объясняйте, чем автор подкрепляет свою позицию.','Read texts with different viewpoints and explain the evidence behind each author’s position.'):t('Читайте короткие тексты регулярно: выделяйте главную мысль, затем находите детали.','Read short texts regularly: identify the main point, then look for the supporting details.'),
  listening:high?t('Слушайте развёрнутые обсуждения: обращайте внимание на отношение говорящего и скрытые смыслы.','Listen to extended discussions, paying attention to the speaker’s attitude and implied meaning.'):t('Слушайте короткие записи повторно: сначала общий смысл, затем отдельные детали.','Replay short recordings: listen for the overall meaning first, then individual details.')
}[domain];}
function renderResult(){if(!attempt||!getProgress(attempt).complete){go(attempt?'quiz':'home');return;}const report=getReport(attempt,QUESTIONS);const domains=resultDomains(report);const assessed=domains.filter(d=>d.assessed);const known=assessed.map(d=>d.level).filter(Number.isInteger);const overall=report.overall||{};const title=levelLabel(overall);const resultMessage=t(`Здравствуйте, Нұрқанат! Я прошёл(ла) пробную онлайн-диагностику. Предварительный ориентир: ${title}. Хочу уточнить уровень и обсудить подходящую группу.`,`Hello, Nurkanat! I completed the preview online assessment. My provisional estimate is ${title}. I’d like to confirm my level and discuss a suitable course.`);
  app.innerHTML=`${previewBanner()}<div class="app-shell"><div class="app-top container">${brand()}<div class="header-tools">${languageButton()}<button class="text-link" data-action="home">${t('На главную','Back home')} ↗</button></div></div><main id="main" class="container"><section class="result-hero"><p class="section-kicker">${t('ВАШ ПЕРВЫЙ ОРИЕНТИР ГОТОВ','YOUR STARTING POINT IS READY')}</p><h1>${t('Теперь у вас есть<br><span>отправная точка.</span>','Now you have<br><span>a starting point.</span>')}</h1><p>${t('Посмотрите, как складывается ваш профиль. Это предварительная оценка по выполненным заданиям, которую стоит обсудить с преподавателем.','Take a look at your skill profile. This is a provisional estimate from the tasks you completed, ready to discuss with your teacher.')}</p></section><div class="result-layout"><div class="result-main"><section class="result-summary"><div class="report-top"><span class="report-label">${t('ОНЛАЙН-ПРОФИЛЬ','ONLINE PROFILE')}</span><span class="report-badge">${t('Предварительно','Provisional')}</span></div><div class="result-level">${esc(title)}</div><p>${t('Результат относится к этой пробной версии. Он не подтверждает точное положение внутри уровня или общий уровень всех четырёх навыков.','This estimate applies to the preview edition. It does not establish a precise position within a level or your overall ability across all four skills.')}</p><div class="result-skill-list">${domains.map(d=>`<div class="skill-result"><div class="skill-result-heading"><h3>${domainName(d.domain)}</h3><span class="skill-level">${esc(levelLabel(d))}</span></div>${d.assessed?`<p>${getSkillCopy(d.domain,d.level)}</p><p class="evidence-note">${esc(evidenceNote(d,language))}</p><small>${t('Ответов верно','Correct answers')}: ${d.correct} / ${d.total} · ${t('в заданиях разной сложности','across tasks of varying difficulty')}</small>`:`<p>${t('Этот навык не входит в короткий формат.','This skill is not included in the quick route.')}</p>`}</div>`).join('')}<div class="skill-result pending-skills"><div><h3>${t('Речь и письмо','Speaking & writing')}</h3><p>${t('Дополнят картину после оценки преподавателем.','Complete the picture with teacher assessment.')}</p></div><span class="pill">${t('Ещё не оценены','Not yet assessed')}</span></div></div></section><section class="result-next"><p class="section-kicker">${t('ЧТО ДЕЛАТЬ ДАЛЬШЕ','WHAT TO DO NEXT')}</p><h2>${t('Три полезных шага.','Three useful next steps.')}</h2><ol class="priority-list"><li><strong>${t('Выберите один навык для практики','Choose one skill to practise')}</strong><p>${t('Используйте рекомендации выше как отправную точку. Небольшая регулярная практика поможет увидеть, что получается легче.','Use the suggestions above as a starting point. Small, regular practice helps you notice what becomes easier.')}</p></li><li><strong>${t('Уточните речь и письмо','Check your speaking and writing')}</strong><p>${t('Онлайн-задания показывают только часть картины. Разговор и письменная работа дадут дополнительную информацию.','Online tasks show only part of the picture. A conversation and writing task add important evidence.')}</p></li><li><strong>${t('Обсудите подходящий формат','Discuss a suitable learning format')}</strong><p>${t('Расскажите о своих целях и времени на занятия — вместе подберём следующий шаг.','Share your goals and the time you have for learning, and we’ll discuss your next step.')}</p></li></ol></section>${buildFeedback(attempt,QUESTIONS,language).html}<div class="result-actions"><button class="button secondary" data-action="download">${t('Сохранить отчёт','Save my report')} ↓</button><button class="text-link" data-action="print">${t('Печать / PDF','Print / PDF')} ↗</button><button class="text-link" data-action="share">${t('Поделиться ссылкой на тест','Share the assessment link')} ↗</button><button class="text-link" data-action="prepare" data-mode="${attempt.mode==='quick'?'full':'full'}">${attempt.mode==='quick'?t('Добавить аудирование','Try the route with listening'):t('Пройти заново','Try again')} ↻</button></div></div><aside class="result-sidebar"><div class="result-course-card"><span class="pill">${t('ВАШ СЛЕДУЮЩИЙ ШАГ','YOUR NEXT STEP')}</span><h2>${t('Продолжим<br>вместе?','Let’s take the<br>next step together.')}</h2><p>${t('Нұрқанат поможет уточнить результат и обсудить группу под ваши цели.','Nurkanat can help confirm your result and discuss a group that fits your goals.')}</p><div class="result-course-options"><div><strong>${t('Стандартный','Standard')}</strong><span>~6 ${t('месяцев','months')}</span></div><div><strong>${t('Интенсив','Intensive')}</strong><span>~3 ${t('месяца','months')}</span></div></div><a class="button primary wide" href="${waLink(resultMessage)}" target="_blank" rel="noopener">${t('Обсудить мою группу','Discuss my course')} ${arrow}</a><small>${t('Примерная длительность программы на уровень. Стоимость и расписание — лично.','Approximate programme duration per level. Ask about fees and schedules.')}</small><div class="result-teacher"><img src="assets/teacher.jpg" alt="" width="48" height="48"><div>${t('Нұрқанат Дайраш','Nurkanat Dairash')}<span>${t('Ваш преподаватель','Your teacher')}</span></div></div></div><div class="result-note"><strong>${t('Ваш результат принадлежит вам.','Your result is yours to keep.')}</strong><p>${t('Записываться на курс необязательно. В этой версии отчёт хранится только в вашем браузере.','Joining a course is optional. In this edition, your report is stored only in your browser.')}</p></div></aside></div><div class="result-bottom-note">${t('Методика этой версии ещё проверяется. Точность шкалы не установлена; отметки A1–C1 обозначают предварительные ориентиры.','This edition’s method is still being evaluated. Scale accuracy has not been established; A1–C1 labels are provisional indicators.')}</div></main></div>`;
}
function reportText(){const report=getReport(attempt,QUESTIONS);const lines=[t('Нұрқанат Дайраш — пробная диагностика английского','Nurkanat Dairash — English assessment preview'),new Date().toLocaleDateString(language==='ru'?'ru-RU':'en-GB'),'',t('Предварительный онлайн-профиль','Provisional online profile'),...resultDomains(report).map(d=>`${domainName(d.domain)}: ${levelLabel(d)}${d.assessed?` (${d.correct}/${d.total})`:''}${d.assessed?' — '+evidenceNote(d,language):''}`),'',t('Речь и письмо: не оценены.','Speaking and writing: not assessed.'),t('Шкала и задания ещё проверяются. Это не официальный экзамен или точная оценка CEFR.','Questions and scoring are still being evaluated. This is not an official exam or a precise CEFR assessment.'),'',t('Следующий шаг: обсудить результат и учебные цели с преподавателем.','Next step: discuss your result and learning goals with your teacher.'),WA];return lines.join('\n')+'\n\n'+buildFeedback(attempt,QUESTIONS,language).text;}
function download(){const blob=new Blob(['\ufeff'+reportText()],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`english-profile-${language}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Отчёт сохранён в текстовом формате.','Your report has been saved as a text file.'));}
function privacy(){openModal(`<p class="section-kicker">${t('ПРОЗРАЧНО О ДАННЫХ','ABOUT YOUR DATA')}</p><h2 id="modal-title">${t('Ваши ответы — на вашем устройстве.','Your answers stay on your device.')}</h2><p>${t('Эта версия не запрашивает имя, почту или данные карты. Ответы и выбранный язык сохраняются в локальном хранилище браузера. Разработчик сайта не получает их автоматически.','This edition does not request your name, email, or card details. Answers and your chosen language are stored in your browser’s local storage. The site developer does not automatically receive them.')}</p><p>${t('Хостинг может обрабатывать технические данные посещения. При переходе в WhatsApp вы пользуетесь отдельным сервисом и сами отправляете подготовленное сообщение.','The hosting service may process technical visit information. WhatsApp is a separate service; you choose whether to send the prepared message.')}</p><p>${t('Сохранённые ответы можно удалить кнопкой ниже. Это действие нельзя отменить.','You can remove your saved answers below. This cannot be undone.')}</p><div class="modal-actions"><button class="button secondary" data-action="delete-data">${t('Удалить мои ответы','Delete my answers')}</button><button class="button primary" data-action="close">${t('Понятно','Got it')}</button></div>`);}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;if(el.tagName==='A'&&action==='home')event.preventDefault();switch(action){case'language':language=language==='ru'?'en':'ru';try{localStorage.setItem(LANG,language);}catch{}closeModal();render();break;case'home':go('home');break;case'prepare':prepare(el.dataset.mode);break;case'preflight':preflight(el.dataset.mode);break;case'start':start(el.dataset.mode);break;case'close':closeModal();break;case'resume':go(attempt&&getProgress(attempt).complete?'result':'quiz');break;case'pause':save();go('home');break;case'answer':choose(Number(el.dataset.index));break;case'unknown':choose(null);break;case'submit':submit();break;case'retry-audio':$('#audio-error').hidden=true;$('#question-audio').load();break;case'download':download();break;case'print':document.querySelectorAll('.feedback-section details').forEach(el=>el.open=true);window.print();break;case'privacy':privacy();break;case'delete-data':if(storageConflict){location.reload();return;}attempt=null;heard=new Set();try{localStorage.removeItem(STORE);}catch{}go('home');toast(t('Ответы удалены с этого устройства.','Your answers have been deleted from this device.'));break;case'share':{const url=new URL('./',location.href).href;try{await navigator.clipboard.writeText(url);toast(t('Ссылка скопирована. В личном предпросмотре её видит только владелец.','Link copied. This private preview is visible only to its owner.'));}catch{openModal(`<h2 id="modal-title">${t('Ссылка на диагностику','Assessment link')}</h2><p>${t('Предпросмотр доступен только владельцу.','This preview is available only to its owner.')}</p><input class="share-input" readonly value="${esc(url)}" aria-label="${t('Ссылка','Link')}">`);}break;}}});
document.addEventListener('keydown',event=>{const overlay=$('#overlay');if(overlay.hidden)return;if(event.key==='Escape'){event.preventDefault();closeModal();}if(event.key==='Tab'){const nodes=[...overlay.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),audio[controls]')];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('modal'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
$('#overlay').addEventListener('click',event=>{if(event.target===$('#overlay'))closeModal();});
window.addEventListener('storage',event=>{if(event.key===STORE){storageConflict=true;saveOk=false;updateNext();openModal(`<h2 id="modal-title">${t('Попытка открыта в другом окне','Your attempt changed in another tab')}</h2><p>${t('Чтобы не перезаписать ответы, обновите страницу и продолжите в одном окне.','To avoid overwriting answers, reload this page and continue in one tab.')}</p><button class="button primary" id="reload-page">${t('Обновить страницу','Reload page')}</button>`);$('#reload-page').onclick=()=>location.reload();}});
render();
